const data = $input.first().json.data || {};
const products = Array.isArray(data.products) ? data.products : [data];
if (products.length === 0 || !products[0].product_id) {
  return [{ json: { none: true } }];
}
return products.map((product) => ({ json: {
  product_id: product.product_id,
  prompt: 'Write an SEO meta title (max 60 characters), meta description (max 155 characters), a short description (max 300 characters) and a description of 120 to 200 words for this product. Use only the facts given; do not invent regions, prices or delivery times.\n\nAnswer with JSON only: an array of objects, each with \"title\" (string), \"body\" (string) and \"rationale\" (string), plus any fields the task asks for. Use only the data given; never invent sales figures, prices, stock or supplier availability. Everything you write is a draft that a person reviews before anything is published.\n\nProduct data (JSON):\n' + JSON.stringify(product),
} }));

const prompts = $('Build prompts').all().filter((item) => item.json.none !== true);
const drafts = [];
$input.all().forEach((item, index) => {
  const text = String(item.json.text || '');
  const start = text.indexOf('[');
  const end = text.lastIndexOf(']');
  let parsed = [];
  try {
    parsed = JSON.parse(start >= 0 && end > start ? text.slice(start, end + 1) : text);
  } catch (error) {
    parsed = [];
  }
  (Array.isArray(parsed) ? parsed : [parsed]).slice(0, 10).forEach((draft) => {
    if (draft && typeof draft === 'object' && typeof draft.title === 'string' && draft.title.trim() !== '') {
      drafts.push({ json: { body: { type: 'seo_description', product_id: prompts[index] ? prompts[index].json.product_id : null, content: { ...draft, title: draft.title.slice(0, 255) } } } });
    }
  });
});
if (drafts.length === 0) {
  throw new Error('The model returned no usable drafts (expected a JSON array of objects with a title).');
}
return drafts;

