const data = $input.first().json.data || {};
const money = (v) => (v && typeof v === 'object' && !Array.isArray(v) && 'amount' in v && 'currency' in v) ? v.amount + ' ' + v.currency : null;
const label = (row) => {
  const name = row.name || row.product_name || row.platform || row.supplier || row.gateway || row.order_number || row.command || row.variant_sku || row.code || row.sku;
  const figure = money(row.net_revenue) || money(row.revenue) || money(row.sales) || money(row.net_profit) || row.units_count || row.state || row.status || row.margin_pct;
  return name ? (figure !== undefined && figure !== null ? name + ': ' + figure : String(name)) : JSON.stringify(row).slice(0, 80);
};
const lines = [];
const render = (obj, prefix, depth) => {
  for (const [key, value] of Object.entries(obj)) {
    if (['unavailable', 'note', 'basis', 'source', 'reason', 'status', 'alert'].includes(key) && depth === 0) continue;
    if (value === null || value === undefined) continue;
    const name = prefix + key;
    const m = money(value);
    if (m) { lines.push(name + ': ' + m); continue; }
    if (Array.isArray(value)) {
      lines.push(name + ': ' + value.length);
      value.slice(0, 5).forEach((row) => lines.push('  - ' + (typeof row === 'object' && row !== null ? label(row) : String(row))));
      continue;
    }
    if (typeof value === 'object') { if (depth < 2) render(value, name + '.', depth + 1); continue; }
    lines.push(name + ': ' + value);
  }
};
render(data, '', 0);
for (const missing of (data.unavailable || [])) lines.push('Unavailable: ' + missing.metric + ' (' + missing.reason + ')');
if (data.status === 'unavailable') lines.push('Unavailable: ' + data.reason);
const alert = data.alert === true;
return [{ json: { notify: data.drafts_stored > 0, severity: 'info', title: 'C08 Generate SEO Descriptions: drafts awaiting review', text: lines.slice(0, 60).join('\n'), source: 'C08', summary: { alert } } }];

